// Clarity answers with an array of {metricName, information: [...]} - nine
// blocks, one per metric, each holding its own list of rows. It is metric major,
// not page major, so this unnests it into one flat row per metric per page per
// device and the pivot happens in the next node.
//
// n8n's HTTP Request node splits a top-level JSON array into one item per
// element, so this usually arrives as nine items. The other shapes are handled
// too because getting it wrong produces zero rows and a clean green run.
const raw = $('Fetch Clarity Friction').all().map((x) => x.json);
const blocks = [];
for (const r of raw) {
  if (Array.isArray(r)) blocks.push(...r);
  else if (Array.isArray(r.body)) blocks.push(...r.body);
  else if (Array.isArray(r.data)) blocks.push(...r.data);
  else if (r && r.metricName) blocks.push(r);
}

const out = [];
for (const block of blocks) {
  const metric = String(block.metricName || '');
  const rows = Array.isArray(block.information) ? block.information : [];
  for (const row of rows) {
    // Capital U, lowercase rl. The request parameter is spelled dimension1=URL
    // but the key that comes back is `Url`, and `row.URL` is undefined on every
    // single row.
    const url = row.Url;
    if (!url) continue;
    out.push({ json: {
      metric: metric,
      url: String(url),
      device: String(row.Device || 'all'),
      // Counts arrive as STRINGS, percentages as numbers. Uncast, the sums
      // below concatenate instead of adding and every page looks catastrophic.
      sessions: Number(row.sessionsCount || 0),
      affected_percent: Number(row.sessionsWithMetricPercentage || 0),
      events: Number(row.subTotal || 0),
      // Microsoft's documented sample calls these distantUserCount and
      // PagesPerSessionPercentage. The live API does not - it returns
      // distinctUserCount and pagesPerSessionPercentage. Both spellings are read
      // so code written from either source works.
      total_sessions: Number(row.totalSessionCount || 0),
      bot_sessions: Number(row.totalBotSessionCount || 0),
      users: Number(row.distinctUserCount || row.distantUserCount || 0),
      scroll_depth: Number(row.averageScrollDepth || 0),
      active_time: Number(row.activeTime || 0),
    } });
  }
}

// Never return zero items. A Code node that emits nothing ends the branch, and
// a quiet day would then look exactly like a broken workflow.
if (!out.length) {
  return [{ json: { no_clarity_rows: true, blocks_seen: blocks.length } }];
}
return out;

// Pivots the flat rows into one row per page, then decides which pages are
// worth a scrape.
const cfg = $('Settings').first().json;
const minSessions = Number(cfg.min_sessions);
const minPercent = Number(cfg.min_friction_percent);
const maxPages = Number(cfg.max_pages);
const onlyWorse = cfg.only_new_or_worse === true || cfg.only_new_or_worse === 'true';

// Rage, dead and error clicks and script errors are someone failing to do a
// thing. Excessive scrolling and quick backs are someone unhappy, which is worth
// reporting but is not evidence of a broken element, so they do not drive the
// ranking.
const SEVERE = ['RageClickCount', 'ErrorClickCount', 'DeadClickCount', 'ScriptErrorCount'];
const MILD = ['ExcessiveScroll', 'QuickbackClick'];

// Clarity keys on the full URL, so the same article shows up once per query
// string it was reached with - the test project had one page under
// ?utm_source=chatgpt.com and again under ?utm_source=copilot.com. Left split,
// each fragment carries a fraction of the sessions and none of them clears the
// threshold, so a genuinely broken page reports as fine.
function normalise(u) {
  const s = String(u || '').split('#')[0].split('?')[0];
  return s.replace(/\/+$/, '') || s;
}

// Clarity records whatever was in the address bar. One real row was the home
// page with a URL-encoded sentence appended, from somebody pasting a search into
// it. Fetching that spends a request and gives the model a page that was never
// on the site.
function junkReason(u) {
  let dec = String(u || '');
  try { dec = decodeURIComponent(dec); } catch (e) { return 'the URL cannot be decoded'; }
  if (/\s/.test(dec)) return 'the URL contains a space';
  if (dec.length > 300) return 'the URL is absurdly long';
  if (!/^https?:\/\/[^\/]+/.test(dec)) return 'not an http address';
  return '';
}

const pages = {};
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.url) continue;
  const key = normalise(j.url);
  const page = pages[key] || (pages[key] = {
    page_url: key,
    sessions: 0,
    devices: {},
    metrics: {},
    junk: junkReason(j.url),
    variants: 0,
  });
  page.variants += 1;
  if (j.metric === 'Traffic') {
    page.sessions += j.total_sessions;
    page.devices[j.device] = (page.devices[j.device] || 0) + j.total_sessions;
  } else if (SEVERE.indexOf(j.metric) >= 0 || MILD.indexOf(j.metric) >= 0) {
    const m = page.metrics[j.metric] || (page.metrics[j.metric] = { events: 0, affected: 0 });
    m.events += j.events;
    // sessionsWithMetricPercentage is a share of that row's sessions, so it has
    // to be turned back into a count before rows can be added together. Adding
    // the percentages themselves would produce numbers over 100.
    m.affected += Math.round(j.sessions * j.affected_percent / 100);
  }
}

// The history sheet is the only trend available - Clarity cannot be asked for
// anything older than three days and has no offset parameter. An empty sheet
// emits one blank item, which is why every row is checked for page_url.
const previous = {};
for (const h of $('Read Friction History').all()) {
  const r = h.json || {};
  if (!r.page_url) continue;
  previous[String(r.page_url)] = Number(r.friction_percent || 0);
}

const ranked = [];
for (const key of Object.keys(pages)) {
  const p = pages[key];
  if (p.junk) continue;
  if (p.sessions < minSessions) continue;

  let severe = 0;
  let mild = 0;
  const detail = [];
  for (const name of SEVERE.concat(MILD)) {
    const m = p.metrics[name];
    if (!m || (!m.events && !m.affected)) continue;
    detail.push(name.replace(/Count$/, '') + ': ' + m.events + ' event' + (m.events === 1 ? '' : 's') + ' across ' + m.affected + ' session' + (m.affected === 1 ? '' : 's'));
    if (SEVERE.indexOf(name) >= 0) severe += m.affected;
    else mild += m.affected;
  }

  const percent = Math.round(severe / p.sessions * 100);
  if (percent < minPercent) continue;

  const was = previous[key];
  const seenBefore = was !== undefined;
  if (onlyWorse && seenBefore && percent <= was) continue;

  const devices = Object.keys(p.devices)
    .sort((a, b) => p.devices[b] - p.devices[a])
    .map((d) => d + ' ' + p.devices[d]);

  ranked.push({
    page_url: key,
    sessions: p.sessions,
    friction_sessions: severe,
    friction_percent: percent,
    unhappy_sessions: mild,
    previous_percent: seenBefore ? was : null,
    trend: !seenBefore ? 'first time it has crossed the line'
      : 'was ' + was + '%, now ' + percent + '%',
    breakdown: detail.join('; '),
    devices: devices.join(', '),
  });
}

ranked.sort((a, b) => (b.friction_percent - a.friction_percent) || (b.sessions - a.sessions));
const picked = ranked.slice(0, maxPages);

if (!picked.length) {
  return [{ json: {
    nothing_broken: true,
    pages_seen: Object.keys(pages).length,
  } }];
}
return picked.map((p) => ({ json: p }));

// The Web Unlocker returns markdown as plain text, so nothing about which page
// produced it survives into the item. It emits one item per input item in the
// same order and continues on error rather than dropping an item, so the join
// back to the ranked pages is positional. There is no field here to match on.
const ranked = $('Rank Friction Pages').all().map((x) => x.json);
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = ranked[i];
  if (!src || !src.page_url) continue;
  const j = items[i].json || {};

  // Bright Data answers validation errors and rate limits with HTTP 200 and an
  // error body, and neverError swallows the status, so the body is the only
  // place a failure shows up.
  if (j.error || j.error_message) {
    out.push({ json: { ...src, skipped: 'Bright Data returned: ' + String(j.error || j.error_message).slice(0, 120) } });
    continue;
  }
  const body = String(j.data ?? j.body ?? '');
  if (!body.trim()) {
    out.push({ json: { ...src, skipped: 'the page came back empty' } });
    continue;
  }

  const h1 = body.match(/^#\s+(.+)$/m);
  const headings = [];
  const hre = /^#{2,3}\s+(.+)$/gm;
  let m;
  while ((m = hre.exec(body)) !== null && headings.length < 20) {
    const h = m[1].replace(/[*_`\[\]]/g, '').trim();
    if (h && h.length < 120) headings.push(h);
  }

  // The anchor text of what is clickable is the most useful thing on the page
  // for this question, because a dead click is usually something that looks
  // like a control and is not one. Markdown only carries real links though - a
  // div styled as a button is invisible here, and the prompt says so rather
  // than letting the model assume it saw everything.
  const links = [];
  const lre = /\[([^\]]{2,60})\]\(([^)\s]+)/g;
  const seen = {};
  while ((m = lre.exec(body)) !== null && links.length < 25) {
    const text = m[1].replace(/[*_`]/g, '').trim();
    if (!text || seen[text]) continue;
    seen[text] = true;
    links.push(text);
  }

  out.push({ json: {
    ...src,
    page_title: h1 ? h1[1].slice(0, 140) : '',
    headings: headings,
    link_texts: links,
    word_count: body.split(/\s+/).length,
  } });
}

// Same rule as the nodes above: this must never empty the branch.
if (!out.length) {
  return [{ json: { nothing_broken: true, pages_seen: 0 } }];
}
return out;

