// The Information Extractor does not merge its answer into the item, it
// REPLACES it - every row arrives as {output: {...}} and nothing else. The page
// URL is gone by this point, so the join back is positional, on the same order
// the extractor received. Matching on a field that no longer exists finds
// nothing and leaves every page undiagnosed on a fully green run.
const outlined = $('Outline The Page').all().map((x) => x.json);
const items = $input.all();
const stamp = new Date().toISOString().slice(0, 10);
const rows = [];

// The model ignores the schema's enum often enough to plan for - three earlier
// templates drifted on exactly this - so confidence is folded back to the three
// values the sheet is allowed to hold.
function normaliseConfidence(v) {
  const s = String(v || '').toLowerCase();
  if (s.startsWith('h')) return 'high';
  if (s.startsWith('l')) return 'low';
  return 'medium';
}

for (let i = 0; i < items.length; i++) {
  const src = outlined[i];
  if (!src || !src.page_url) continue;
  const j = items[i].json || {};
  const a = (j.output && typeof j.output === 'object') ? j.output : j;

  rows.push({
    checked_on: stamp,
    page_url: src.page_url,
    sessions: src.sessions,
    friction_sessions: src.friction_sessions,
    friction_percent: src.friction_percent,
    unhappy_sessions: src.unhappy_sessions,
    previous_percent: src.previous_percent === null ? '' : src.previous_percent,
    devices: src.devices,
    breakdown: src.breakdown,
    likely_cause: String(a.likely_cause || '').slice(0, 500),
    element_to_check: String(a.element_to_check || '').slice(0, 200),
    recommended_fix: String(a.recommended_fix || '').slice(0, 500),
    confidence: normaliseConfidence(a.confidence),
  });
}

// A page that could not be fetched still belongs in the report and, just as
// importantly, still belongs in the sheet - it is the sheet that decides what
// counts as "already seen" on the next run, so dropping it here would make the
// same page report as brand new every single day.
for (const src of outlined) {
  if (!src || !src.page_url || !src.skipped) continue;
  if (rows.some((r) => r.page_url === src.page_url)) continue;
  rows.push({
    checked_on: stamp,
    page_url: src.page_url,
    sessions: src.sessions,
    friction_sessions: src.friction_sessions,
    friction_percent: src.friction_percent,
    unhappy_sessions: src.unhappy_sessions,
    previous_percent: src.previous_percent === null ? '' : src.previous_percent,
    devices: src.devices,
    breakdown: src.breakdown,
    likely_cause: 'not diagnosed: ' + src.skipped,
    element_to_check: '',
    recommended_fix: 'open this page and its Clarity recordings by hand',
    confidence: 'low',
  });
}

if (!rows.length) {
  return [{ json: { nothing_broken: true, pages_seen: 0 } }];
}
return rows.map((r) => ({ json: r }));

// Reads the report rows by name rather than from this node's input, because a
// Google Sheets append sits in between and returns its own confirmation shape.
const rows = $('Build Friction Report').all().map((x) => x.json).filter((r) => r.page_url);
const cfg = $('Settings').first().json;

if (!rows.length) {
  return [{ json: { message: 'Clarity friction check ran and found nothing new.' } }];
}

// min_sessions is a user setting, so "1 sessions" is reachable on any small
// site that lowers it. Pluralise every count rather than only the ones that
// happened to be noticed.
const plural = (n, word) => n + ' ' + word + (Number(n) === 1 ? '' : 's');

const lines = [
  '*Clarity friction* - ' + plural(rows.length, 'page') +
    ' where people are getting stuck, last ' + plural(cfg.clarity_days, 'day'),
  '',
];

for (const r of rows) {
  lines.push('*' + r.page_url + '*  ' + r.friction_percent + '% of ' + plural(r.sessions, 'session'));
  lines.push('   ' + r.breakdown);
  if (r.devices) lines.push('   seen on ' + r.devices);
  lines.push('   ' + r.likely_cause);
  if (r.element_to_check) lines.push('   *Look at:* ' + r.element_to_check);
  lines.push('   *Do:* ' + r.recommended_fix + '  _(' + r.confidence + ' confidence)_');
  lines.push('');
}

lines.push('Full detail in the sheet. Reported at ' + cfg.min_friction_percent + '% of sessions or more, on pages with at least ' + plural(cfg.min_sessions, 'session') + '.');

return [{ json: { message: lines.join('\n') } }];

// Optional. Splice between 'Flatten Clarity Metrics' and 'Rank Friction Pages'
// on a site where thousands of URLs share a handful of templates. Clarity
// reports per URL, so a broken product page looks like 400 small problems
// instead of one big one. This rolls /product/123 and /product/456 into
// /product/* and sums their sessions before anything is ranked.
const groups = {};
for (const item of items) {
  const j = item.json || {};
  const key = String(j.page_url || '')
    .replace(/\/\d+(?=\/|$)/g, '/*')
    .replace(/\/[0-9a-f]{8,}(?=\/|$)/gi, '/*');
  if (!groups[key]) groups[key] = { page_url: key, sessions: 0, rage_clicks: 0, dead_clicks: 0, script_errors: 0, urls_merged: 0 };
  const g = groups[key];
  g.sessions += Number(j.sessions) || 0;
  g.rage_clicks += Number(j.rage_clicks) || 0;
  g.dead_clicks += Number(j.dead_clicks) || 0;
  g.script_errors += Number(j.script_errors) || 0;
  g.urls_merged += 1;
}
return Object.values(groups).map((g) => ({ json: g }));
